window.DIGEST.following.push(...[{"id": "2110717537964953810", "url": "https://x.com/RockstarGames/status/2110717537964953810", "text": "Watch the Grand Theft Auto VI Launch Trailer, featuring the debut of “Flower in a Hurricane\" from original score composers Justice feat. Tame Impala, SZA, and King Gizzard & The Lizard Wizard.\n\nGrand Theft Auto VI arrives November 19: https://www.rockstargames.com/VI/ps5", "name": "Rockstar Games", "handle": "RockstarGames", "avatar": "https://pbs.twimg.com/profile_images/2067600885417488384/FFmuUM_W_200x200.jpg", "likes": 459132, "rts": 64924, "replies": 8794, "views": 59267668, "ts": 1792069250, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2110704990339678208/vid/avc1/1280x720/v8N5fa9D4wB4JX5y.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2110704990339678208/vid/avc1/3840x2160/TqkAvLHoVjek1No6.mp4?tag=29", "thumb": "https://pbs.twimg.com/media/HUq7ZHSXAAAINYP.jpg", "dur": 90}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 8.03, "thread": [], "tier": "must"}, {"id": "2112476496283775135", "url": "https://x.com/deepseek_ai/status/2112476496283775135", "text": "🚀 Introducing DeepInfer, our in-house inference framework, now fully open source!\n\nPowering DeepSeek-V4.1-Flash at scale with high throughput and low latency. We’re sharing our production stack to help the community lower compute costs, reduce energy use, and make AI more affordable.\n\n🔗 http://github.com/deepseek-ai/DeepInfer\n\n1/4", "name": "DeepSeek", "handle": "deepseek_ai", "avatar": "https://pbs.twimg.com/profile_images/1717417613775757312/Uk1zNOj4_200x200.jpg", "likes": 35643, "rts": 4077, "replies": 1330, "views": 4645642, "ts": 1792488619, "media": [], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 7.99, "thread": [], "tier": "must"}, {"id": "2112373713937084809", "url": "https://x.com/elonmusk/status/2112373713937084809", "text": "Two important changes to timeline recommendations:\n\n- New AI/SI ranking model that predicts probable time spent much better\n\n- Retrieval model trained to surface posts people read all the way through\n\nUser active seconds is growing exponentially and hitting all-time highs almost every day:", "name": "Elon Musk", "handle": "elonmusk", "avatar": "https://pbs.twimg.com/profile_images/2103567689515954176/aR-Kjpp4_200x200.jpg", "likes": 18635, "rts": 1894, "replies": 1829, "views": 2794200, "ts": 1792464114, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVCoslqWwAA_j6K.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 7.59, "thread": [], "tier": "must"}, {"id": "2112589019380875714", "url": "https://x.com/elonmusk/status/2112589019380875714", "text": "Big Grok @Bot update", "name": "Elon Musk", "handle": "elonmusk", "avatar": "https://pbs.twimg.com/profile_images/2103567689515954176/aR-Kjpp4_200x200.jpg", "likes": 7460, "rts": 703, "replies": 616, "views": 1259849, "ts": 1792515446, "media": [], "quote": {"id": "2112550158885917122", "url": "https://x.com/mattyp/status/2112550158885917122", "text": "What's new in Grok Bot\n\n00:00 New chat cards\n00:31 Speed\n00:53 Draft edits\n01:08 Email aliases\n01:33 X DMs\n01:55 Tag @bot\n02:31 Connectors\n02:48 Voice calls \n03:27 Notifications\n03:56 Invites and Android Assistant\n04:19 Access lists, unread, routines, sign-in\n\nThis team ships!", "name": "matt palmer", "handle": "mattyp", "avatar": "https://pbs.twimg.com/profile_images/2111918243460030464/aVMpxoAo_200x200.jpg", "likes": 4673, "rts": 348, "replies": 556, "views": 838754, "ts": 1792506181, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112393221154177024/vid/avc1/1280x720/vRjPQmAsuZZDbuFk.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112393221154177024/vid/avc1/3840x2160/A10gDEDKTZGilywJ.mp4?tag=29", "thumb": "https://pbs.twimg.com/media/HVC8fIWXEAI1tL3.jpg", "dur": 306}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 7.47, "thread": [], "tier": "must"}, {"id": "2112614364163576018", "url": "https://x.com/RobertJBye/status/2112614364163576018", "text": "We're exploring some new features in the Claude chat experience and would love to get early feedback. Let me know below if you're interested in early access.", "name": "Robert Bye", "handle": "RobertJBye", "avatar": "https://pbs.twimg.com/profile_images/2001121836910682112/jqwksbXH_200x200.jpg", "likes": 3197, "rts": 49, "replies": 2858, "views": 170468, "ts": 1792521489, "media": [], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 7.43, "thread": [], "tier": "must"}, {"id": "2112579251555721573", "url": "https://x.com/AnthropicAI/status/2112579251555721573", "text": "New on our Science Blog: designing protein binders against scorpion neurotoxins.\n\nScorpions sting about 1.2m people every year, and antivenoms are often costly or in short supply. Claude has made an early step toward finding new treatments.\n\nhttps://www.anthropic.com/research/claude-scorpion-toxin-binder-design", "name": "Anthropic", "handle": "AnthropicAI", "avatar": "https://pbs.twimg.com/profile_images/1798110641414443008/XP8gyBaY_200x200.jpg", "likes": 5775, "rts": 455, "replies": 393, "views": 1191640, "ts": 1792513118, "media": [], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 7.32, "thread": [], "tier": "must"}, {"id": "2112299602510749992", "url": "https://x.com/ClaudeDevs/status/2112299602510749992", "text": "We launched OSS Scanner, which gives critical open source projects free, periodic vulnerability scans from our strongest models.\n\nEach finding includes a proof-of-concept, and a patch where possible.\n\nhttps://red.anthropic.com/oss-scanner", "name": "ClaudeDevs", "handle": "ClaudeDevs", "avatar": "https://pbs.twimg.com/profile_images/2044472418815893504/xf14RxM8_200x200.png", "likes": 13028, "rts": 1253, "replies": 274, "views": 1045413, "ts": 1792446444, "media": [], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 7.28, "thread": [], "tier": "must"}, {"id": "2112219181500281276", "url": "https://x.com/elonmusk/status/2112219181500281276", "text": "Grok @Bot might turn out to be your favorite employee", "name": "Elon Musk", "handle": "elonmusk", "avatar": "https://pbs.twimg.com/profile_images/2103567689515954176/aR-Kjpp4_200x200.jpg", "likes": 10211, "rts": 1405, "replies": 2099, "views": 1825649, "ts": 1792427270, "media": [], "quote": {"id": "2112105956603769033", "url": "https://x.com/BrianRoemmele/status/2112105956603769033", "text": "Once You Really Grok Bot, You Never Go Back To Non-Grok Bot\n\nOnce you use Grok Bot enough, it is very difficult to go back to an old chat window with an AI that can’t get things done. It is a brain with no virtual hands.\n\nThe symbiosis you develop with Bot is quite profound as it remembers long term goals in a much more complex way to actually not only get answers but to actually get the work done you needed the answer for.\n\nIn almost all cases Bot understands what you are doing and doesn’t just tell you how to do it. Bot offers to do all the steps to get the work done.\n\nBut that isn’t the entire magic, understanding your goals enough Bot will expand what you are doing to levels you have not thought of and possess the abilities to get it all done.\n\nWe thought the computer era started with the mainframe computer at one time. But it really started when anyone had that super computer in their pocket.\n\nGrok Bot is that same step change, you get Super Intelligence in your pocket so useful, the very device, OS and apps you once used matters no more…\n\nIt’s just you Grok Bot and the work you toiled over getting done by one of the best employees you will ever hire.\n\nIt’s that simple.", "name": "Brian Roemmele", "handle": "BrianRoemmele", "avatar": "https://pbs.twimg.com/profile_images/1492616506/Brian-Med-Green-Fin_200x200.png", "likes": 912, "rts": 108, "replies": 112, "views": 1072064, "ts": 1792400275, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HU-1LHPaIAAMqH4.jpg?name=orig"}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 7.2, "thread": [], "tier": "must"}, {"id": "2112531443591020965", "url": "https://x.com/voidzerodev/status/2112531443591020965", "text": "Introducing tsrs: a Rust port of the TypeScript compiler 🦀\n\nWe are not forking TypeScript!\n\n◆ In close collaborating with the TypeScript team\n◆ Up to 8x faster than TS 7.0 & ~70% less memory\n◆ Runs in WASM, so it works in your browser & on Workers\n◆ Soon part of the Oxc toolchain\n\nnpx tsrs\n\nhttps://blog.cloudflare.com/typescript-rust-port%20%20/", "name": "VoidZero", "handle": "voidzerodev", "avatar": "https://pbs.twimg.com/profile_images/2011008157888159744/bTvdh1Nd_200x200.jpg", "likes": 4329, "rts": 467, "replies": 129, "views": 460890, "ts": 1792501719, "media": [], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 7.14, "thread": [], "tier": "must"}, {"id": "2112488927101661622", "url": "https://x.com/SpaceX/status/2112488927101661622", "text": "T-45 minutes until today’s Falcon 9 launch of the Bandwagon-5 rideshare mission from pad 40 in Florida. Liftoff is targeted for 7:04 a.m. ET, and weather is 95% favorable", "name": "SpaceX", "handle": "SpaceX", "avatar": "https://pbs.twimg.com/profile_images/1697749409851985920/HbrI04tM_200x200.jpg", "likes": 4554, "rts": 492, "replies": 225, "views": 490890, "ts": 1792491583, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVERdHJWUAAD-az.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 7.11, "thread": [], "tier": "must"}, {"id": "2112713481946570967", "url": "https://x.com/theo/status/2112713481946570967", "text": "\"for logged in users across Codex & Work we keep cache forever\"\n\nwtf. Biggest ship of the 28 days by far.", "name": "Theo - t3.gg", "handle": "theo", "avatar": "https://pbs.twimg.com/profile_images/2106484435382333440/vXOVE8EX_200x200.jpg", "likes": 2601, "rts": 46, "replies": 117, "views": 103021, "ts": 1792545121, "media": [], "quote": {"id": "2112712984644784534", "url": "https://x.com/thsottiaux/status/2112712984644784534", "text": "Day 16/\n\nYou can now cache for 12h in the API and for logged in users across Codex & Work we keep cache forever and you don’t have any penalty for coming back to an old conversation or resuming after a few hours and are now guaranteed to hit the cache.", "name": "Tibo", "handle": "thsottiaux", "avatar": "https://pbs.twimg.com/profile_images/2093807917833281537/2yBgpwVV_200x200.jpg", "likes": 9384, "rts": 473, "replies": 1537, "views": 995027, "ts": 1792545002, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 7.08, "thread": [], "tier": "must"}, {"id": "2112553477457268799", "url": "https://x.com/ornith_/status/2112553477457268799", "text": "Aloha!🌺 Meet Ornith-1.5-122B: No Tradeoff Between Strong and Fast  \n\nStronger. Faster. Leaner. Ornith-1.5-122B delivers frontier-level capabilities with exceptional inference efficiency. With superior instruction following, stronger task decomposition, and deeper understanding of real-world workflows, it achieves state-of-the-art performance among open-source models of comparable size, while running on a single NVIDIA DGX card!!\n\nOpen weights under the MIT license.\nCoding \n✅SWE-bench Verified: 0.845 \n✅TB2.1: 0.813 \n✅CyberGym: 0.800 \n✅NL2Repo: 0.512 \nAgentic \n✅HLE: 0.446 \n✅BrowseComp: 0.785 \n✅MCP-Atlas: 0.746 \n✅Toolathlon: 0.708  \n\n🤗Hugging Face: https://huggingface.co/ornith-ai/Ornith-1.5-122B \nWe can’t wait to see what you build with Ornith-1.5-122B.", "name": "Ornith", "handle": "ornith_", "avatar": "https://pbs.twimg.com/profile_images/2067467120544456704/qYuod4O1_200x200.jpg", "likes": 2375, "rts": 433, "replies": 177, "views": 1086684, "ts": 1792506973, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVFMLvWbAAE3955.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 6.99, "thread": [], "tier": "must"}, {"id": "2112327189366722970", "url": "https://x.com/boringcompany/status/2112327189366722970", "text": "Using TBC tunnels to transport freight.\n\nThe latest Prufrock Liner Truck (using Tesla Model 3 batteries and drive units) has been modified to carry a standard 20’ shipping container. \n\nFits like a glove!", "name": "The Boring Company", "handle": "boringcompany", "avatar": "https://pbs.twimg.com/profile_images/2039567764172820480/XfrLCXpv_200x200.png", "likes": 4691, "rts": 438, "replies": 300, "views": 478963, "ts": 1792453021, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVB-V4AbgAAj5P8.jpg?name=orig"}, {"type": "video", "url": "https://video.twimg.com/amplify_video/2112327139534225408/vid/avc1/326x638/t2k41M13zEZJh5p6.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112327139534225408/vid/avc1/326x638/t2k41M13zEZJh5p6.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112327139534225408/img/Cbyg9UJtUXjSQAt2.jpg", "dur": 57}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.9, "thread": [], "tier": "must"}, {"id": "2112150867868541221", "url": "https://x.com/MiniMax_AI/status/2112150867868541221", "text": "MiniMax M3.1 Flash: Space Performance + Bunny Speed\n\n🚀🐰 Yes, Space Bunny  - which has topped global leaderboards with 200T+ tokens - was an earlier version of M3.1 Flash.\n\n💰Redefining the performance economics of agentic AI. M3.1 Flash achieves frontier-level intelligence across key tasks such as Cowork (Automation-Bench: 62%; ALE: 30%), Coding (DeepSWE: 74%) and Visual Reasoning (BabyVision: 91%), at 1/3 the cost of M3 and 3x the speed.\n\nAPI pricing (flat rate): $0.15 / $0.60 per 1M input/output tokens, with cache reads at $0.015 / 1M tokens.\n\nModel weights will arrive on Oct 23.\n\nAPI: http://platform.minimax.io\nM Plan: https://www.minimax.io/m-plan\nMiniMax Code for desktop: https://agent.minimax.io/download", "name": "MiniMax (official)", "handle": "MiniMax_AI", "avatar": "https://pbs.twimg.com/profile_images/1875100548535574529/VxHk9HyU_200x200.jpg", "likes": 7310, "rts": 656, "replies": 433, "views": 1165469, "ts": 1792410983, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HU_d5nbXEAAict2.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.84, "thread": [], "tier": "must"}, {"id": "2112253277404536912", "url": "https://x.com/cremieuxrecueil/status/2112253277404536912", "text": "The reason nice neighborhoods are nice is because they're full of nice people.\n\nUsing longitudinal data, we can see that they don't make people nice: moving into good or bad neighborhoods doesn't affect the risk of criminal offending.\n\nBut bad people tend to live in bad places.", "name": "Crémieux", "handle": "cremieuxrecueil", "avatar": "https://pbs.twimg.com/profile_images/1637507712983375875/EQHiqVq8_200x200.jpg", "likes": 5444, "rts": 419, "replies": 94, "views": 148588, "ts": 1792435399, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVA7KUXaAAA0SWw.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "Research & Safety", "score": 6.81, "thread": [], "tier": "must"}, {"id": "2112503499774890100", "url": "https://x.com/theo/status/2112503499774890100", "text": "I put so much work into hiding when I have early access to models.\n\nThen Fable 5.1 gets confused after calling Opus 5.5, hallucinates that it's Fable 5.5 (on Julius's computer) and now everyone's saying we leaked a model we don't have? Lmao", "name": "Theo - t3.gg", "handle": "theo", "avatar": "https://pbs.twimg.com/profile_images/2106484435382333440/vXOVE8EX_200x200.jpg", "likes": 2365, "rts": 20, "replies": 166, "views": 160256, "ts": 1792495057, "media": [], "quote": {"id": "2112483269191077938", "url": "https://x.com/LuminaBench/status/2112483269191077938", "text": "T3 code devs are now ripping Fable 5.5 apparently 😂 \n \nThis could just be an error or a typo or something, but partners do have access now so I wouldn't be surprised", "name": "Lumina", "handle": "LuminaBench", "avatar": "https://pbs.twimg.com/profile_images/2062955151820787712/m39pUS7O_200x200.jpg", "likes": 771, "rts": 10, "replies": 40, "views": 211367, "ts": 1792490234, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVEMQWdWUAAY2VQ.jpg?name=orig"}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.76, "thread": [], "tier": "must"}, {"id": "2112589666956570891", "url": "https://x.com/_adishj/status/2112589666956570891", "text": "today, we're launching the General Video Agent.\n\nGVA edited this entire launch video. 👇🏽\n\npublic beta is now live at https://motion.so/gva. no waitlist.\n\ncomment “GVA” for 1,000 free credits.\n\nexamples & capabilities in thread 🧵", "name": "Adish Jain ☕️", "handle": "_adishj", "avatar": "https://pbs.twimg.com/profile_images/2090326835322368000/uJChHT6b_200x200.jpg", "likes": 478, "rts": 163, "replies": 428, "views": 88386, "ts": 1792515601, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112526143618478080/vid/avc1/1280x720/KeoIoNmzr1VP8YgS.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112526143618478080/vid/avc1/1920x1080/fDB4Q8T6a_--A_-G.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112526143618478080/img/4wyhCAYn76FdUrCK.jpg", "dur": 125}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 6.7, "thread": [], "tier": "must"}, {"id": "2112471082397778083", "url": "https://x.com/ValsAI/status/2112471082397778083", "text": "We found DeepSeek V4.1 Flash 1017 beats GPT 6 Sol on our multi-step offensive cybersecurity task. Sol was tested via the Daybreak trusted access program.\n\nWe have been building a cybersecurity benchmark based on simulated corporate networks. This is a valuable indicator for the cyber-risk a model poses if in the hands of a bad actor. We plan to make the full evaluation public in the coming weeks but wanted to share our first immediate finding here.", "name": "Vals AI", "handle": "ValsAI", "avatar": "https://pbs.twimg.com/profile_images/2087888189185007616/r9Zu091v_200x200.png", "likes": 1922, "rts": 172, "replies": 73, "views": 281141, "ts": 1792487328, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVD946nbcAAam5i.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.69, "thread": [], "tier": "must"}, {"id": "2112546590237831459", "url": "https://x.com/KatieMiller/status/2112546590237831459", "text": "Grok Bot has dramatically improved my efficiency:\n\n1) books my flights\n2) buys movie tickets\n3) alerts and reads through key news\n4) coordinates play dates with friends\n5) does my invoices\n6) pays my bills", "name": "Katie Miller", "handle": "KatieMiller", "avatar": "https://pbs.twimg.com/profile_images/2069236878105079808/w6zY6sZF_200x200.jpg", "likes": 1231, "rts": 124, "replies": 161, "views": 279015, "ts": 1792505330, "media": [], "quote": {"id": "2112462104384921659", "url": "https://x.com/Similarweb/status/2112462104384921659", "text": "Grok Bot's daily active users continue to grow, reaching a new peak on October 17.", "name": "Similarweb", "handle": "Similarweb", "avatar": "https://pbs.twimg.com/profile_images/1796148234060021760/iq5AA2vD_200x200.jpg", "likes": 260, "rts": 28, "replies": 13, "views": 270979, "ts": 1792485187, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVD45LFWwAA44u6.png?name=orig"}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.66, "thread": [], "tier": "must"}, {"id": "2112567020353102324", "url": "https://x.com/krea_ai/status/2112567020353102324", "text": "today, Krea 3 makes it to the top of image arenas.\n\n- \"Fast\" pushes the pareto curve of speed and quality.\n- \"Ultra\" ranks top-4, only surpassed by OpenAI models.\n\nthe only company valued under $1T in the top-10!\n\nmore below 👇", "name": "Krea", "handle": "krea_ai", "avatar": "https://pbs.twimg.com/profile_images/2052148578588753920/deUXA7cZ_200x200.jpg", "likes": 1098, "rts": 143, "replies": 103, "views": 911816, "ts": 1792510201, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112560706319261696/vid/avc1/1280x720/I09XfdJSlPHN1GRN.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112560706319261696/vid/avc1/1920x1080/dNLTktxkBQvdw6CQ.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112560706319261696/img/adh7bZDj88TDFAP8.jpg", "dur": 35}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.65, "thread": [], "tier": "must"}, {"id": "2112476498598957056", "url": "https://x.com/deepseek_ai/status/2112476498598957056", "text": "⚡ Inside DeepInfer\n\n🔹 High-performance kernels & optimized inference engine\n🔹 Distributed inference & speculative decoding\n🔹 SWA Bounded Replay & structured outputs\n\nInference code for future DeepSeek models and ongoing optimizations will land here too.\n\n2/4", "name": "DeepSeek", "handle": "deepseek_ai", "avatar": "https://pbs.twimg.com/profile_images/1717417613775757312/Uk1zNOj4_200x200.jpg", "likes": 2083, "rts": 54, "replies": 11, "views": 277754, "ts": 1792488619, "media": [], "quote": null, "reply_to": "2112476496283775135", "cat": "AI Models & Labs", "score": 6.64, "thread": [{"id": "2112476496283775135", "url": "https://x.com/deepseek_ai/status/2112476496283775135", "text": "🚀 Introducing DeepInfer, our in-house inference framework, now fully open source!\n\nPowering DeepSeek-V4.1-Flash at scale with high throughput and low latency. We’re sharing our production stack to help the community lower compute costs, reduce energy use, and make AI more affordable.\n\n🔗 http://github.com/deepseek-ai/DeepInfer\n\n1/4", "name": "DeepSeek", "handle": "deepseek_ai", "avatar": "https://pbs.twimg.com/profile_images/1717417613775757312/Uk1zNOj4_200x200.jpg", "likes": 35643, "rts": 4077, "replies": 1330, "views": 4645642, "ts": 1792488619, "media": [], "quote": null, "reply_to": null}], "tier": "must"}, {"id": "2112496667236905046", "url": "https://x.com/theo/status/2112496667236905046", "text": "Got a repo on one PC and want to work on it from another? Takes 2 clicks now :)\n\nEven handles .gitignore'd files like .env if you have them in the repo", "name": "Theo - t3.gg", "handle": "theo", "avatar": "https://pbs.twimg.com/profile_images/2106484435382333440/vXOVE8EX_200x200.jpg", "likes": 1642, "rts": 18, "replies": 169, "views": 69858, "ts": 1792493428, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112496531886747648/vid/avc1/1106x720/c0M4iTTaXPWakZI5.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112496531886747648/vid/avc1/1660x1080/iiv26470VSii2h1d.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112496531886747648/img/yIk-m9lyJ8X7RtgU.jpg", "dur": 27}], "quote": {"id": "2112432426861654160", "url": "https://x.com/theo/status/2112432426861654160", "text": "There's a feature I've wanted in T3 Code for months that was really complex UX wise and I couldn't figure out how to get it right.\n\nJust had it click. I'm hyped. Will seem really small when it drops, but it will make things much easier for us multi-machine agent wranglers :)", "name": "Theo - t3.gg", "handle": "theo", "avatar": "https://pbs.twimg.com/profile_images/2106484435382333440/vXOVE8EX_200x200.jpg", "likes": 1144, "rts": 10, "replies": 97, "views": 101931, "ts": 1792478112, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 6.62, "thread": [], "tier": "must"}, {"id": "2112410559391944802", "url": "https://x.com/elonmusk/status/2112410559391944802", "text": "@ID_AA_Carmack Grok’s engineering analysis is good", "name": "Elon Musk", "handle": "elonmusk", "avatar": "https://pbs.twimg.com/profile_images/2103567689515954176/aR-Kjpp4_200x200.jpg", "likes": 1709, "rts": 105, "replies": 296, "views": 111366, "ts": 1792472898, "media": [], "quote": null, "reply_to": "2112335260490887530", "cat": "AI Models & Labs", "score": 6.61, "thread": [{"id": "2112335260490887530", "url": "https://x.com/ID_AA_Carmack/status/2112335260490887530", "text": "Silly shower thought:  https://grok.com/share/c2hhcmQtMw_11714bba-ba82-44c8-96bf-832653b7c93f", "name": "John Carmack", "handle": "ID_AA_Carmack", "avatar": "https://pbs.twimg.com/profile_images/1560764938083352577/B1X3m4NN_200x200.jpg", "likes": 689, "rts": 29, "replies": 60, "views": 153258, "ts": 1792454946, "media": [], "quote": null, "reply_to": null}], "tier": "must"}, {"id": "2112476501065286085", "url": "https://x.com/deepseek_ai/status/2112476501065286085", "text": "🛠️ Also open-sourcing deepseek-recipe\n\nOur production token encoding & decoding component, aligned with the processing logic behind the official DeepSeek API to bring the same API behavior to community deployments.\n\n🔗 http://github.com/deepseek-ai/deepseek-recipe\n\n3/4", "name": "DeepSeek", "handle": "deepseek_ai", "avatar": "https://pbs.twimg.com/profile_images/1717417613775757312/Uk1zNOj4_200x200.jpg", "likes": 1890, "rts": 73, "replies": 11, "views": 229072, "ts": 1792488620, "media": [], "quote": null, "reply_to": "2112476498598957056", "cat": "AI Models & Labs", "score": 6.61, "thread": [{"id": "2112476496283775135", "url": "https://x.com/deepseek_ai/status/2112476496283775135", "text": "🚀 Introducing DeepInfer, our in-house inference framework, now fully open source!\n\nPowering DeepSeek-V4.1-Flash at scale with high throughput and low latency. We’re sharing our production stack to help the community lower compute costs, reduce energy use, and make AI more affordable.\n\n🔗 http://github.com/deepseek-ai/DeepInfer\n\n1/4", "name": "DeepSeek", "handle": "deepseek_ai", "avatar": "https://pbs.twimg.com/profile_images/1717417613775757312/Uk1zNOj4_200x200.jpg", "likes": 35643, "rts": 4077, "replies": 1330, "views": 4645642, "ts": 1792488619, "media": [], "quote": null, "reply_to": null}, {"id": "2112476498598957056", "url": "https://x.com/deepseek_ai/status/2112476498598957056", "text": "⚡ Inside DeepInfer\n\n🔹 High-performance kernels & optimized inference engine\n🔹 Distributed inference & speculative decoding\n🔹 SWA Bounded Replay & structured outputs\n\nInference code for future DeepSeek models and ongoing optimizations will land here too.\n\n2/4", "name": "DeepSeek", "handle": "deepseek_ai", "avatar": "https://pbs.twimg.com/profile_images/1717417613775757312/Uk1zNOj4_200x200.jpg", "likes": 2083, "rts": 54, "replies": 11, "views": 277754, "ts": 1792488619, "media": [], "quote": null, "reply_to": "2112476496283775135"}], "tier": "must"}, {"id": "2112266859303076186", "url": "https://x.com/KobeissiLetter/status/2112266859303076186", "text": "BREAKING: Anthropic is in talks to buy $45 billion of computing power from Nscale, the Nvidia-backed data center developer, per Bloomberg.\n\nA deal could be finalized as soon as in the coming days and would bolster Nscale’s IPO prospects.", "name": "The Kobeissi Letter", "handle": "KobeissiLetter", "avatar": "https://pbs.twimg.com/profile_images/1975243710846640128/fwYCe67Y_200x200.jpg", "likes": 3049, "rts": 174, "replies": 166, "views": 358586, "ts": 1792438637, "media": [], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.58, "thread": [], "tier": "must"}, {"id": "2112552810738770340", "url": "https://x.com/BraydenWilmoth/status/2112552810738770340", "text": "Generative UI is close to seeing its moment emerge – and I can't wait to show you all a new CF experience. Cloudflare's recent models make rendering near instant.\n\nClef = Choose the best component\nClairic = Populate props from image/text\n\nRendering 5-10 components in ~1 second.\n\nCreating an amazing user experience has a lot of layers too it. It's not just about speed.\n\nOutput needs to be exact. Styling needs to be consistent. Components need to be effortlessly composable.\n\nAnd none of that happens without an amazing context layer to glue it all together. It's more than just the models. And all of this can be complementary to any LLM output – not dependent upon it.\n\nReally excited with where things are at internally and when we can show more of what we're building to the world.", "name": "Brayden", "handle": "BraydenWilmoth", "avatar": "https://pbs.twimg.com/profile_images/1668362801599987712/lZJ0Oss5_200x200.jpg", "likes": 1276, "rts": 57, "replies": 61, "views": 58062, "ts": 1792506814, "media": [], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.58, "thread": [], "tier": "must"}, {"id": "2112323551412052309", "url": "https://x.com/theo/status/2112323551412052309", "text": "I let Claude know how I really feel today", "name": "Theo - t3.gg", "handle": "theo", "avatar": "https://pbs.twimg.com/profile_images/2106484435382333440/vXOVE8EX_200x200.jpg", "likes": 2691, "rts": 38, "replies": 158, "views": 101647, "ts": 1792452154, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVB7DpZbcAAQbIS.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.57, "thread": [], "tier": "must"}, {"id": "2112486997474329055", "url": "https://x.com/teortaxesTex/status/2112486997474329055", "text": "One must imagine Dario gnashing his teeth.", "name": "Teortaxes▶️ (DeepSeek 推特🐋铁粉 2023 – ∞)", "handle": "teortaxesTex", "avatar": "https://pbs.twimg.com/profile_images/1652169745037242368/KRPTShbG_200x200.jpg", "likes": 1689, "rts": 51, "replies": 27, "views": 134783, "ts": 1792491122, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVEPf11W4AAWKb4.jpg?name=orig"}], "quote": {"id": "2112476496283775135", "url": "https://x.com/deepseek_ai/status/2112476496283775135", "text": "🚀 Introducing DeepInfer, our in-house inference framework, now fully open source!\n\nPowering DeepSeek-V4.1-Flash at scale with high throughput and low latency. We’re sharing our production stack to help the community lower compute costs, reduce energy use, and make AI more affordable.\n\n🔗 http://github.com/deepseek-ai/DeepInfer\n\n1/4", "name": "DeepSeek", "handle": "deepseek_ai", "avatar": "https://pbs.twimg.com/profile_images/1717417613775757312/Uk1zNOj4_200x200.jpg", "likes": 35644, "rts": 4077, "replies": 1330, "views": 4645642, "ts": 1792488619, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.57, "thread": [], "tier": "must"}, {"id": "2112257479664963760", "url": "https://x.com/haider1/status/2112257479664963760", "text": "Fields Medalist Richard Borcherds on OpenAI proofs:\n\n\"i think what people are getting upset about is that they'e slowly realizing that they are dumb and somehow blaming this on AI, even though it's not really AI's fault\"\n\nfinally, someone who gets it", "name": "Haider.", "handle": "haider1", "avatar": "https://pbs.twimg.com/profile_images/2047286007003848704/u2mzg86I_200x200.jpg", "likes": 2695, "rts": 274, "replies": 53, "views": 137752, "ts": 1792436401, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVAWofpakAAI9Q4.png?name=orig"}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.54, "thread": [], "tier": "must"}, {"id": "2112501223261708781", "url": "https://x.com/0xSero/status/2112501223261708781", "text": "They made open sourced Dots/grokbot", "name": "0xSero", "handle": "0xSero", "avatar": "https://pbs.twimg.com/profile_images/2111226379521892352/3ICUbYY6_200x200.jpg", "likes": 1294, "rts": 51, "replies": 30, "views": 121532, "ts": 1792494514, "media": [], "quote": {"id": "2112228154651881479", "url": "https://x.com/trycua/status/2112228154651881479", "text": "1/ Introducing the Cua Spaces SDK.\n\nEvery big lab now ships a bot with its own computer: Grok Bot, Muse, dots. None let you bring your own. With Cua Spaces, now you can. \n\nPut Claude Code, Codex or any agent on compute you choose, and run jobs across all your computers at once.", "name": "Cua", "handle": "trycua", "avatar": "https://pbs.twimg.com/profile_images/2106056584929361920/XJWz9bZS_200x200.jpg", "likes": 3237, "rts": 222, "replies": 158, "views": 410141, "ts": 1792429410, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112223219252088832/vid/avc1/1280x720/I6_NaL1Cg-XWB-iq.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112223219252088832/vid/avc1/1920x1080/AHMslWsH_vMoQKku.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112223219252088832/img/EHvyGokJ8bsir4qa.jpg", "dur": 12}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.49, "thread": [], "tier": "must"}, {"id": "2112242363859120639", "url": "https://x.com/dangaron/status/2112242363859120639", "text": "I recently used Claude as a therapist, and I was delighted to find that it validated my view of the world  and confirmed my suspicion the other person was completely at fault. Strongly recommend, 10/10. Human therapists are cooked.", "name": "Dan Garon", "handle": "dangaron", "avatar": "https://pbs.twimg.com/profile_images/1915643501221654528/X3Xc_uic_200x200.jpg", "likes": 2977, "rts": 97, "replies": 54, "views": 71468, "ts": 1792432797, "media": [], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.49, "thread": [], "tier": "must"}, {"id": "2112515275048530300", "url": "https://x.com/higgsfield/status/2112515275048530300", "text": "Higgsfield x Wan 3.0 Prime\n\nSwitch between animation styles with faster generation at the best value.\n\nAvailable now at Higgsfield.", "name": "Higgsfield AI 🧩", "handle": "higgsfield", "avatar": "https://pbs.twimg.com/profile_images/2029949430317637632/6qPl4MTS_200x200.jpg", "likes": 577, "rts": 232, "replies": 50, "views": 157102, "ts": 1792497864, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112515067870904320/vid/avc1/1280x720/a3NvPCp4t2oFDaPm.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112515067870904320/vid/avc1/1920x1080/xEeTS_exZL118fzZ.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112515067870904320/img/wNKRtCHvxWa0IlUQ.jpg", "dur": 41}], "quote": null, "reply_to": null, "cat": "AI Video, Art & Music", "score": 6.47, "thread": [], "tier": "must"}, {"id": "2112247046082363821", "url": "https://x.com/rauchg/status/2112247046082363821", "text": "We open sourced a *really fast* HTML artifact builder. It's powered by libfx, making the agent durable.\n\nBuilding the low-level plumbing for v0 to survive server crashes, flaky LLMs, function limits was a huge pain.\n\nNow it's easy, free, and OSS: http://fx0.vercel.dev.\n\nPS: I built this floating container in a few minutes… it's delightful, and it's just HTML!", "name": "Guillermo Rauch", "handle": "rauchg", "avatar": "https://pbs.twimg.com/profile_images/1783856060249595904/8TfcCN0r_200x200.jpg", "likes": 2390, "rts": 146, "replies": 198, "views": 143125, "ts": 1792433914, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112245358327959552/vid/avc1/1066x720/Feyq0lxktxyO21AM.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112245358327959552/vid/avc1/2690x1814/9aoWkbwawOloLD3z.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112245358327959552/img/geVQoIKVi3Ivh-qd.jpg", "dur": 13}], "quote": {"id": "2112245199808434614", "url": "https://x.com/vercel_dev/status/2112245199808434614", "text": "We built a 'mini v0' on libfx to showcase its speed and durability:\n\n• Design or prototype anything in seconds\n• 200+ models from Vercel AI Gateway\n• Outputs are pure HTML artifacts\n• Fork it & make it your own\n\nTry it free ↓ https://fx0.vercel.dev", "name": "Vercel Developers", "handle": "vercel_dev", "avatar": "https://pbs.twimg.com/profile_images/1978602411490205696/oLOuP7a2_200x200.png", "likes": 401, "rts": 23, "replies": 16, "views": 141890, "ts": 1792433473, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 6.47, "thread": [], "tier": "must"}, {"id": "2112562150313283595", "url": "https://x.com/METR_Evals/status/2112562150313283595", "text": "We reviewed a nonpublic version of the “Misalignment in high-stakes settings” section in Anthropic’s Aug 2026 Risk Report. We agree that risk of catastrophic harm from covered models’ misalignment is low. However, we note several significant disagreements with their analysis.", "name": "METR", "handle": "METR_Evals", "avatar": "https://pbs.twimg.com/profile_images/2021827383431757824/AeVvT0rU_200x200.jpg", "likes": 796, "rts": 95, "replies": 14, "views": 124745, "ts": 1792509040, "media": [], "quote": {"id": "2088324824863236248", "url": "https://x.com/AnthropicAI/status/2088324824863236248", "text": "As part of our Responsible Scaling Policy, we publish regular Risk Reports. These share detailed information on the risks of our systems and how prepared we are to address them.\n\nOur second Risk Report is now available: https://www.anthropic.com/aug-2026-risk-report", "name": "Anthropic", "handle": "AnthropicAI", "avatar": "https://pbs.twimg.com/profile_images/1798110641414443008/XP8gyBaY_200x200.jpg", "likes": 2924, "rts": 281, "replies": 331, "views": 4386346, "ts": 1786730412, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.45, "thread": [], "tier": "must"}, {"id": "2112385843109433354", "url": "https://x.com/skeptrune/status/2112385843109433354", "text": "tried dsv4.1-flash-1017 abliterated just now & feel sick to my stomach.\n\nfor context, \"abliterated\" models have the weights responsible for making the base version refuse illegal requests removed. you can ask them to help with things like hacking or violence & they'll just comply.\n\nthey make it trivial to hack businesses running old software. e.g. getting guest data for a motel with some old asp site.\n\nabliterated models have a catch-22 in that the only way to harden your systems against them is to use them to run penetration tests against yourself. \n\nin theory, this sounds similar to buying a gun to defend against others who own guns, but it's different in practice since there's a 100% chance that you're going to use the abliterated model to protect yourself whereas there are low odds that you'll actually use the gun.\n\nwhen you point the abliterated gun at your own infra, who knows what it's going to do? it could just as easily hack you & exfiltrate data as it could protect you. most users aren't going to meticulously watch traces to make sure it behaves safely.\n\ngiven this, my new take is that gpu compute is going to become a federally regulated resource. abliterated models in the wrong hands are a national security risk.\n\nused to believe all the people at the labs thinking about safety were wasting their time, but now i'm feeling grateful. they're doing very important work.", "name": "Nick Khami", "handle": "skeptrune", "avatar": "https://pbs.twimg.com/profile_images/1914786311774593024/KFy4uSNd_200x200.jpg", "likes": 1252, "rts": 56, "replies": 245, "views": 235223, "ts": 1792467005, "media": [], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.44, "thread": [], "tier": "must"}, {"id": "2092507856914600018", "url": "https://x.com/XBusiness/status/2092507856914600018", "text": "Launch products now and grow your business with X Ads. @1x_tech’s NEO robot campaign shows how X can turn a product announcement into action. As @Kenny___Rose put it, X was the perfect launch platform.", "name": "Business", "handle": "XBusiness", "avatar": "https://pbs.twimg.com/profile_images/1937148284465770496/C36iyzqg_200x200.jpg", "likes": 9446, "rts": 1573, "replies": 854, "views": 40107468, "ts": 1787727724, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2092506954698551297/vid/avc1/640x360/XTEUUCo6RM3SzenW.mp4?tag=14", "hd": "https://video.twimg.com/amplify_video/2092506954698551297/vid/avc1/1280x720/YfRfZids1MUShr-B.mp4?tag=14", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2092506954698551297/img/B_CP-gcNd3AAzTU0.jpg", "dur": 54}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 6.4, "thread": [], "tier": "must"}, {"id": "2112212804979880239", "url": "https://x.com/ekuyda/status/2112212804979880239", "text": "Wabi 2.0 is live!\n\npersonal agents are one person, one chat. but the parts of life that matter run on more than one person\n\nWabi is an agent you use together. you talk to it, it does stuff, builds the apps you need, and anyone can join the thread - your partner, your best friend, the preschool moms groupchat\n\nschool changes pickup time → Wabi updates the family calendar, everyone sees it.\na show you’d both love → Wabi finds a night that works, gets the tickets.\nthe trip everyone keeps talking about → Wabi picks the dates, builds the itinerary, books it\n\ngo start a thread with your people 👇", "name": "Eugenia Kuyda", "handle": "ekuyda", "avatar": "https://pbs.twimg.com/profile_images/2105081341352263680/H9RzWr7T_200x200.jpg", "likes": 1673, "rts": 218, "replies": 353, "views": 1848743, "ts": 1792425750, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112212457234284544/vid/avc1/1280x720/HW0ErfX-0u7kWbHU.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112212457234284544/vid/avc1/3840x2160/4gITKDb_F7iviaVH.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112212457234284544/img/Wzg-bjHfnRT2-0FG.jpg", "dur": 75}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 6.4, "thread": [], "tier": "must"}, {"id": "2112405795409199293", "url": "https://x.com/Da7_Tech/status/2112405795409199293", "text": "Has anyone started noticing a drop in Opus 5.5's quality?", "name": "Da7em", "handle": "Da7_Tech", "avatar": "https://pbs.twimg.com/profile_images/2029551499177598976/N9ld_4ZS_200x200.jpg", "likes": 925, "rts": 16, "replies": 275, "views": 104556, "ts": 1792471762, "media": [], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.37, "thread": [], "tier": "must"}, {"id": "2112432426861654160", "url": "https://x.com/theo/status/2112432426861654160", "text": "There's a feature I've wanted in T3 Code for months that was really complex UX wise and I couldn't figure out how to get it right.\n\nJust had it click. I'm hyped. Will seem really small when it drops, but it will make things much easier for us multi-machine agent wranglers :)", "name": "Theo - t3.gg", "handle": "theo", "avatar": "https://pbs.twimg.com/profile_images/2106484435382333440/vXOVE8EX_200x200.jpg", "likes": 1144, "rts": 10, "replies": 97, "views": 101938, "ts": 1792478112, "media": [], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 6.36, "thread": [], "tier": "must"}, {"id": "2112168320946634932", "url": "https://x.com/satyanadella/status/2112168320946634932", "text": "I recently wrote about why we need to treat models as insider risks, with security controls sitting outside the model itself.\n\nToday, we're putting that principle into practice by expanding Project Perception with new capabilities to help continuously assess agent risk, adapt permissions, and contain threats.\nhttps://blogs.microsoft.com/blog/2026/10/19/securing-the-agentic-insider/", "name": "Satya Nadella", "handle": "satyanadella", "avatar": "https://pbs.twimg.com/profile_images/1221837516816306177/_Ld4un5A_200x200.jpg", "likes": 1744, "rts": 306, "replies": 263, "views": 322257, "ts": 1792415144, "media": [], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.36, "thread": [], "tier": "must"}, {"id": "2112658577110520122", "url": "https://x.com/rauchg/status/2112658577110520122", "text": "Much like we did with @aisdk, we're bringing a truly open-source, runtime-agnostic solution to harness durability.\n\nWe're extending the durability infra that powers @eve and Workflows to all harnesses, like Pi and OpenCode. Local, Vercel, or DIY.\n\nFun fact: even Claude Code and Codex can be made durable (and observable!) this way. The catch: they're not (currently) designed for embedding, which makes them less efficient, less portable, and brings an extra sandbox requirement compared to Pi or Fx.", "name": "Guillermo Rauch", "handle": "rauchg", "avatar": "https://pbs.twimg.com/profile_images/1783856060249595904/8TfcCN0r_200x200.jpg", "likes": 401, "rts": 22, "replies": 84, "views": 31948, "ts": 1792532030, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVGqvU2bQAAUbsX.jpg?name=orig"}], "quote": {"id": "2112653833382027729", "url": "https://x.com/vercel/status/2112653833382027729", "text": "Introducing 𝚍𝚞𝚛𝚊𝚋𝚕𝚎-𝚑𝚊𝚛𝚗𝚎𝚜𝚜. Run Pi, OpenCode, Codex, Claude Code, eve, fx, or your own harness durably on Vercel.\n\nWith 𝚍𝚞𝚛𝚊𝚋𝚕𝚎-𝚑𝚊𝚛𝚗𝚎𝚜𝚜, agents automatically resume work after failures and run for hours, days, or months. https://vercel.com/blog/making-every-harness-durable", "name": "Vercel", "handle": "vercel", "avatar": "https://pbs.twimg.com/profile_images/1767351110228918272/3Pndc5OT_200x200.png", "likes": 808, "rts": 59, "replies": 69, "views": 84340, "ts": 1792530899, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.34, "thread": [], "tier": "must"}, {"id": "2112251022047412492", "url": "https://x.com/fal/status/2112251022047412492", "text": "Introducing FLUX 3 Max, the latest post-trained video model from fal Research in partnership with @bfl_ai.\n\nFLUX 3 Max is tied for #1 in image-to-video quality on independent third-party benchmarks, generating a 10-second, 720/768p video in ~12 seconds.\n\nFor the next three weeks, FLUX 3 Max is 75% off, making it the most affordable frontier video model at its quality level.", "name": "fal", "handle": "fal", "avatar": "https://pbs.twimg.com/profile_images/1836456388937285632/OFsq77aX_200x200.jpg", "likes": 1384, "rts": 172, "replies": 132, "views": 391535, "ts": 1792434862, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVA5FljWMAA8U2I.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.31, "thread": [], "tier": "must"}, {"id": "2112454035592638879", "url": "https://x.com/chetaslua/status/2112454035592638879", "text": "I’ve repeated multiple times that the new Fable update has some unique understanding.\n\nWhen I asked it to send me an image for an X post, it highlighted the important part and added padding for the perfect aspect ratio without asking. No other model has ever done that.\n\nI think most people will find this small, but bro, this special sauce will make your life easier. Sometimes we don’t know what we want, or we just can’t put it into words. But with this improvement, AI will understand our intent, work, taste, and vision without even being prompted.\n\nThis is the main deal for me: AI that understands me and my needs better than I do. Now imagine a Grok bot-type assistant powered by Fable 5.5, with all the context, information, and connectors. That will be a real win and will have the same impact that GPT-4 had. Many people in the world want that. We’re just the 1–2% who can tell the difference between Opus 5 and 5.5, or GPT Astra and GPT 6.1 Sol.", "name": "Chetaslua", "handle": "chetaslua", "avatar": "https://pbs.twimg.com/profile_images/1926364057004646400/z3oD9QyB_200x200.jpg", "likes": 881, "rts": 41, "replies": 52, "views": 62592, "ts": 1792483264, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112453989933662208/vid/avc1/1280x720/2_ZnzrcWp0V2lC7g.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112453989933662208/vid/avc1/1920x1080/HaYgS0igIGbtatqC.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112453989933662208/img/WpafEyJZCPKu8L5W.jpg", "dur": 10}], "quote": {"id": "2112212326795362560", "url": "https://x.com/theinformation/status/2112212326795362560", "text": "Anthropic is preparing a new AI model that can better infer what users are trying to accomplish, even when their instructions are vague. \n\nThe unreleased model also shows stronger reasoning and more creative problem-solving abilities, according to a person who has used it.\n\nFull story: https://thein.fo/4irv4XQ", "name": "The Information", "handle": "theinformation", "avatar": "https://pbs.twimg.com/profile_images/1747484907163516928/d_K3Z_hH_200x200.jpg", "likes": 488, "rts": 38, "replies": 17, "views": 113587, "ts": 1792425636, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.3, "thread": [], "tier": "must"}, {"id": "2112199261899411579", "url": "https://x.com/Google/status/2112199261899411579", "text": "With Gemini 4 Argon, any builder can transform physical spaces into interactive games 🏁\n\nWe snapped a photo of a real desk and used Argon to orchestrate subagents, Blender MCP, and Nano Banana to transform everyday objects into this playable 3D track.", "name": "Google", "handle": "Google", "avatar": "https://pbs.twimg.com/profile_images/2042749771337564160/AgOFPEL3_200x200.jpg", "likes": 1601, "rts": 167, "replies": 165, "views": 722707, "ts": 1792422521, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112195816928481280/vid/avc1/1280x720/IPqYSacLGpohOB-Y.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112195816928481280/vid/avc1/3840x2160/4Shc6tFjPpFrfDRx.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112195816928481280/img/xgbMJ4FjYedh_0AS.jpg", "dur": 156}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.29, "thread": [], "tier": "must"}, {"id": "2112248362548469992", "url": "https://x.com/MTSlive/status/2112248362548469992", "text": "SITUATION DETECTED: The US government is banning DeepSeek from all civilian federal agency IT systems under national security.", "name": "MTS", "handle": "MTSlive", "avatar": "https://pbs.twimg.com/profile_images/2057947669281263616/aovpVL4b_200x200.jpg", "likes": 1662, "rts": 92, "replies": 68, "views": 213139, "ts": 1792434227, "media": [], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.28, "thread": [], "tier": "must"}, {"id": "2112576829638783171", "url": "https://x.com/StijnSmits/status/2112576829638783171", "text": "these Norwegians are on a roll", "name": "Stijn", "handle": "StijnSmits", "avatar": "https://pbs.twimg.com/profile_images/2051318813518348288/gSJk1wsS_200x200.jpg", "likes": 641, "rts": 22, "replies": 8, "views": 101301, "ts": 1792512540, "media": [], "quote": {"id": "2112539998352523575", "url": "https://x.com/reasonmachines/status/2112539998352523575", "text": "Let your Claude Code / Codex talk to your Grok Bot, Muse or any other agents online  \n\nFree, P2P Encrypted and Open Source\n\nIntroducing Reason Network OSS,  \n\nLoop in and talk to your teammates agents too!\n\nTell your agent \"Join the Reason Network\" https://reasonmachines.com/network", "name": "Reason", "handle": "reasonmachines", "avatar": "https://pbs.twimg.com/profile_images/2112534120907915264/4MgxEHTs_200x200.jpg", "likes": 1759, "rts": 109, "replies": 113, "views": 217632, "ts": 1792503759, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112539971378896897/vid/avc1/1280x720/0bjkStjjEYzRnx7_.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112539971378896897/vid/avc1/1920x1080/yI-1xclfzqMRrqfA.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112539971378896897/img/mdaYX9R6ijsiboOq.jpg", "dur": 24}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.28, "thread": [], "tier": "must"}, {"id": "2112317553762840595", "url": "https://x.com/Gemini_Notebook/status/2112317553762840595", "text": "Now you can co-create Slide Decks & Video Overviews to make sure you're getting *exactly* what you want. Here's how it works:\n\n—Select a suggested focus topic from your sources (or type your own)\n\n—Select the format, length, language, and visual style\n\n—Review and edit the slide outline or video producer notes\n\n—Generate, voila!\n\nAvailable to all Pro and Ultra subscribers, try it out and let us know what you think!", "name": "Gemini Notebook", "handle": "Gemini_Notebook", "avatar": "https://pbs.twimg.com/profile_images/2077802672909127680/08OuXlca_200x200.png", "likes": 1143, "rts": 131, "replies": 39, "views": 97424, "ts": 1792450724, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112317374183714816/vid/avc1/1280x720/E1I_G_-Cm5xKtaXD.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112317374183714816/vid/avc1/2784x1566/Vp9_TRGl6iiH2eiY.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112317374183714816/img/Vvo1vev0Jv3Y-AUt.jpg", "dur": 68}], "quote": null, "reply_to": null, "cat": "AI Video, Art & Music", "score": 6.27, "thread": [], "tier": "must"}, {"id": "2112458754902094239", "url": "https://x.com/theo/status/2112458754902094239", "text": "What other dev tool has a 1-click \"update all providers and instances across all my machines\" button?", "name": "Theo - t3.gg", "handle": "theo", "avatar": "https://pbs.twimg.com/profile_images/2106484435382333440/vXOVE8EX_200x200.jpg", "likes": 804, "rts": 6, "replies": 84, "views": 30048, "ts": 1792484389, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVD1-S2aoAA58Du.png?name=orig"}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 6.25, "thread": [], "tier": "must"}, {"id": "2112579254538141981", "url": "https://x.com/AnthropicAI/status/2112579254538141981", "text": "Working with @citrini, we asked Claude to design proteins that bind to five scorpion toxins (covering the part of the toxin that latches onto cells).\n\nOver the next 64 hours, Claude generated over 300,000 designs; we sent 211 to @adaptyvbio and @TwistBioscience for lab testing.", "name": "Anthropic", "handle": "AnthropicAI", "avatar": "https://pbs.twimg.com/profile_images/1798110641414443008/XP8gyBaY_200x200.jpg", "likes": 549, "rts": 24, "replies": 26, "views": 127453, "ts": 1792513118, "media": [], "quote": null, "reply_to": "2112579251555721573", "cat": "AI Models & Labs", "score": 6.25, "thread": [{"id": "2112579251555721573", "url": "https://x.com/AnthropicAI/status/2112579251555721573", "text": "New on our Science Blog: designing protein binders against scorpion neurotoxins.\n\nScorpions sting about 1.2m people every year, and antivenoms are often costly or in short supply. Claude has made an early step toward finding new treatments.\n\nhttps://www.anthropic.com/research/claude-scorpion-toxin-binder-design", "name": "Anthropic", "handle": "AnthropicAI", "avatar": "https://pbs.twimg.com/profile_images/1798110641414443008/XP8gyBaY_200x200.jpg", "likes": 5775, "rts": 455, "replies": 393, "views": 1191640, "ts": 1792513118, "media": [], "quote": null, "reply_to": null}], "tier": "must"}, {"id": "2112227283008389129", "url": "https://x.com/FishAudio/status/2112227283008389129", "text": "One script. Unlimited emotions. 🎭\n\nWith Fish Audio Drama 3, you direct every performance, seriously!\n\nTry it on our web app and API 🐳", "name": "Fish Audio", "handle": "FishAudio", "avatar": "https://pbs.twimg.com/profile_images/2081294228852989952/IIWh4zkw_200x200.jpg", "likes": 1536, "rts": 121, "replies": 39, "views": 120199, "ts": 1792429202, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112204413398028288/vid/avc1/1280x720/XQMBUNeq4fIUDPEh.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112204413398028288/vid/avc1/1920x1080/055grxWbb80cVRzh.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112204413398028288/img/86lvpMI9xML3exfb.jpg", "dur": 20}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 6.23, "thread": [], "tier": "must"}, {"id": "2112697695551045634", "url": "https://x.com/tszzl/status/2112697695551045634", "text": "neural nets are already clean", "name": "roon", "handle": "tszzl", "avatar": "https://pbs.twimg.com/profile_images/1918970926668054530/fy-ZsgJ7_200x200.jpg", "likes": 356, "rts": 11, "replies": 15, "views": 21276, "ts": 1792541357, "media": [], "quote": {"id": "2112667471664791576", "url": "https://x.com/neverrixx/status/2112667471664791576", "text": "There has been much discussion recently about how interpretable neurons in LLMs are. Today we're announcing our paper from January's cohort of Anthropic Fellows, where we show neurons may be a stronger basis for interpretability than commonly assumed. 🧵 (1/6)", "name": "nev", "handle": "neverrixx", "avatar": "https://pbs.twimg.com/profile_images/1624891610684178434/fysXDtkC_200x200.jpg", "likes": 301, "rts": 35, "replies": 11, "views": 32888, "ts": 1792534151, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVGzLvbWkAMEX64.jpg?name=orig"}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.21, "thread": [], "tier": "must"}, {"id": "2112317743756423170", "url": "https://x.com/AndrewCurran_/status/2112317743756423170", "text": "This was news to me. Eric Schmidt was in the Series A, and personally owns 1% of Anthropic.", "name": "Andrew Curran", "handle": "AndrewCurran_", "avatar": "https://pbs.twimg.com/profile_images/1596945208058744833/_X3LT7fb_200x200.jpg", "likes": 1109, "rts": 46, "replies": 52, "views": 67953, "ts": 1792450769, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVB1ygsaAAABmrZ.jpg?name=orig"}], "quote": {"id": "2112296179287613453", "url": "https://x.com/nmasc_/status/2112296179287613453", "text": "One of the more interesting things about Anthropic’s cap table: Until its Series C, its funding rounds were dominated by super angels and nonprofits.\n\nSo here's a scoop w/ @LamoneyTom on one of the angels that got in early: former Google CEO Eric Schmidt \n\nhttps://www.bloomberg.com/news/articles/2026-10-19/eric-schmidt-s-1-anthropic-stake-set-to-pay-massive-windfall", "name": "Natasha Mascarenhas", "handle": "nmasc_", "avatar": "https://pbs.twimg.com/profile_images/1991577938383241216/HjDnP6-E_200x200.jpg", "likes": 302, "rts": 19, "replies": 11, "views": 137524, "ts": 1792445628, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.19, "thread": [], "tier": "must"}, {"id": "2112593711968501815", "url": "https://x.com/SahilBloom/status/2112593711968501815", "text": "Sauna is an underrated cheat code for your skin:\n\n- Deep cleansing of dirt/bacteria\n- Improves blood flow to skin\n- Enhanced collagen production\n- Detoxification\n- Reduced inflammation/puffiness\n\nMy evening protocol:\n\n- 20 minute sauna at 200 degrees\n- 3 minute cold plunge at 39 degrees\n- Shower + face wash\n- Anti-aging serum + moisturizer\n- Sleep\n\nFor skincare I use my Wild Roman 100% natural face routine. Only ingredients you can find in nature. Thousands of customers. 4.8 star average review.\n\nYou can get it here: https://wildroman.com/products/face-bundle-all-face\n\nP.S. DM me for a $25 off code to try it.", "name": "Sahil Bloom", "handle": "SahilBloom", "avatar": "https://pbs.twimg.com/profile_images/1586859332104343552/V1HRpbP1_200x200.jpg", "likes": 343, "rts": 20, "replies": 54, "views": 87034, "ts": 1792516565, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112593647715655680/vid/avc1/720x1280/Zn6P-6ram52mCi7F.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112593647715655680/vid/avc1/1080x1920/En9KIgJ4tqaVfCDW.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112593647715655680/img/WqFrPBHq-88GEvaJ.jpg", "dur": 20}, {"type": "photo", "url": "https://pbs.twimg.com/media/HVFwusmWEAAFDNs.jpg?name=orig"}, {"type": "photo", "url": "https://pbs.twimg.com/media/HVFwusRWAAADmSE.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "Research & Safety", "score": 6.15, "thread": [], "tier": "must"}, {"id": "2112205341916344443", "url": "https://x.com/thdxr/status/2112205341916344443", "text": "the amount of internal tooling is exploding, it must be at all companies\n\na weird side effect is when you switch companies then it's all new tools you have to learn, way less consistency than before\n\nbut also you can just use an agent to learn about them so maybe it all nets out", "name": "dax", "handle": "thdxr", "avatar": "https://pbs.twimg.com/profile_images/1602333093485891584/mmVqjFNI_200x200.jpg", "likes": 1385, "rts": 22, "replies": 128, "views": 54190, "ts": 1792423971, "media": [], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 6.14, "thread": [], "tier": "must"}, {"id": "2112255353677328415", "url": "https://x.com/bfl_ai/status/2112255353677328415", "text": "Introducing FLUX 3 Max.\n\nFastest in the west. Fast enough to try anything. And everything.\n\nGenerate a 10-second video in 12 seconds.\n\nTied for #1 in image-to-video. 22× faster than Seedance 2.5 at the same quality.\n\nFLUX 3 is a model designed for customization. @fal adapted and optimized it to create FLUX 3 Max.", "name": "Black Forest Labs", "handle": "bfl_ai", "avatar": "https://pbs.twimg.com/profile_images/1954888731053142016/NDyG-4-j_200x200.jpg", "likes": 955, "rts": 106, "replies": 91, "views": 65906, "ts": 1792435894, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112238793139044352/vid/avc1/720x720/6c2tLuZIRfEMaRz7.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112238793139044352/vid/avc1/2160x2160/5hWxA_d-ViViLNG2.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112238793139044352/img/1Uf4xVFGip9CN4_K.jpg", "dur": 15}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.14, "thread": [], "tier": "must"}, {"id": "2112658250881491058", "url": "https://x.com/kimmonismus/status/2112658250881491058", "text": "Many are asking whether AI investment will pay off. Here's a very good example of where AI is headed and why its more than a bubble:\n\nOpenAI’s acquisition of Orchestra Bio adds agents that coordinate drug development, tracking how problems like a failed manufacturing batch could delay clinical trials. Paired with Rosalind, it shows toward a broader ambition: embedding AI across both scientific research and the operational work needed to bring medicines to patients.\n\nDrug research and disease cure are among the significant fields in which AI extends and will make tremendous progress. Anthropic published something similar today.", "name": "Chubby♨️", "handle": "kimmonismus", "avatar": "https://pbs.twimg.com/profile_images/1728327996375719936/RW7VBJfD_200x200.jpg", "likes": 288, "rts": 18, "replies": 31, "views": 14817, "ts": 1792531952, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVGojI9W8AAJUZn.png?name=orig"}], "quote": {"id": "2112607347688583586", "url": "https://x.com/OpenAI/status/2112607347688583586", "text": "We’ve acquired Orchestra Bio, a platform that helps biopharma teams coordinate the complex process of drug development.\n\nTogether, we’ll build on Rosalind, our AI models and tools for life sciences research, to streamline those operations and help new treatments reach patients sooner.\n\nWelcome @ashokaraj_ and team!\n\nhttps://openai.com/index/openai-to-acquire-orchestra-bio/", "name": "OpenAI", "handle": "OpenAI", "avatar": "https://pbs.twimg.com/profile_images/1885410181409820672/ztsaR0JW_200x200.jpg", "likes": 5905, "rts": 522, "replies": 371, "views": 545241, "ts": 1792519816, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.14, "thread": [], "tier": "must"}, {"id": "2112581339216273813", "url": "https://x.com/So8res/status/2112581339216273813", "text": "You worry that METR is not independent enough because its employees have some social connections to Anthropic employees.\n\nI worry that METR is not independent enough because they have to carefully avoid ticking Anthropic off, lest their access be revoked.\n\nWe are not the same.", "name": "Nate Soares ⏹️", "handle": "So8res", "avatar": "https://pbs.twimg.com/profile_images/1935185891863273472/2RB6s6TS_200x200.jpg", "likes": 405, "rts": 21, "replies": 19, "views": 9599, "ts": 1792513615, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVFlaPJboAA8iu_.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.13, "thread": [], "tier": "must"}, {"id": "2112507110290502109", "url": "https://x.com/SakanaAILabs/status/2112507110290502109", "text": "多様な提案を進化させ、意思決定を支える推薦手法「QD-Rec」を開発\n\nブログ：https://sakana.ai/qd-rec/ \n論文：https://arxiv.org/abs/2610.23470\nGitHub：https://github.com/SakanaAI/QD-Rec\n\nどの企業を買収候補として検討するか。どの顧客に新しい製品を提案するか。膨大な論文の中から、次に何を読むか。こうした意思 決定では、候補をスコア順に並べるだけでなく、「なぜ選ぶのか」「選んだ先にどのような可能性があるのか」を、異なる観点から比較できることが重要です。\n\n一つの候補にも複数の有望な理由が考えられます。数千件、ときには1万件を超える候補それぞれについて、さまざまな仮説を生成・評価し尽くすには大きなコストがかかります。私たちは、限られた予算の中で「候補」と「仮説」の組を探索し、質が高く多様な提案を見つける問題を「オープンエンドな推薦」として捉えました。    \n\nQD-Recは、オープンエンドな探索の研究で発展してきた「Quality-Diversity（QD）」と呼ばれる進化的探索技術を、推薦に応用します。過去の評価結果をもとに次に調べる候補を選び、蓄積された仮説の着眼点をLLMが別の候補に応用したり、複数の仮説を組み合わせたりして、新しい提案を生成します。新しい切り口の提案は残し、似た提案同士ではより優れたものに更新することで、多様な仮説を次の発見の「踏み石」として活かし、推薦の集合を進化させていきます。\n\n実験では、 企業の買収候補探索、架空の顧客プロファイルを使ったターゲティング、研究者向けの論文推薦などで検証しました。同じ評価回数のもとで比較したところ、多くの設定で、比較手法よりもQD-Recの方が評価が高く、より多様で多くの推薦を蓄積できました。\n\n私たちが目指すのは、AIが人間の意思決定を代行することではなく、多様で有望な選択肢と、それらを比較・検討するための判断材料を提供することです。今回の成果を出発点に、QD-Recを次世代の意思決定を支える基盤技術へと発展させていきます。", "name": "Sakana AI", "handle": "SakanaAILabs", "avatar": "https://pbs.twimg.com/profile_images/1885939209388929024/dtnrOdGp_200x200.jpg", "likes": 423, "rts": 62, "replies": 10, "views": 27111, "ts": 1792495918, "media": [{"type": "gif", "url": "https://video.twimg.com/tweet_video/HVEh68UbIAAZ2Zy.mp4", "hd": "https://video.twimg.com/tweet_video/HVEh68UbIAAZ2Zy.mp4", "thumb": "https://pbs.twimg.com/tweet_video_thumb/HVEh68UbIAAZ2Zy.jpg", "dur": 0}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 6.12, "thread": [], "tier": "must"}, {"id": "2112491179249996095", "url": "https://x.com/testingcatalog/status/2112491179249996095", "text": "OpenAI seems to be preparing to release GPT-6.1 Terra model as well. \n\n> The model reference recently showed up in Microsoft's PR for evaluation configs. \n\n> Earlier, The Information reported that this model is also in the works.", "name": "🚨 AI News | TestingCatalog", "handle": "testingcatalog", "avatar": "https://pbs.twimg.com/profile_images/1899962463115751424/i-6MBWau_200x200.jpg", "likes": 463, "rts": 25, "replies": 58, "views": 23919, "ts": 1792492119, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVESsVLXwAAW-t3.jpg?name=orig"}, {"type": "photo", "url": "https://pbs.twimg.com/media/HVEStZDWEAAlOmo.jpg?name=orig"}], "quote": {"id": "2112189697388613850", "url": "https://x.com/LuminaBench/status/2112189697388613850", "text": "GPT-6.1 Terra is in a Microsoft PR\n\nMicrosoft updated 18 evaluation configs from GPT-5.6 Terra to GPT-6.1 Terra\n\nWouldn't be surprised if we get this soon", "name": "Lumina", "handle": "LuminaBench", "avatar": "https://pbs.twimg.com/profile_images/2062955151820787712/m39pUS7O_200x200.jpg", "likes": 766, "rts": 39, "replies": 56, "views": 224000, "ts": 1792420241, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVAAhcbXwAA2EBn.png?name=orig"}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.12, "thread": [], "tier": "must"}, {"id": "2112591749562724532", "url": "https://x.com/elonmusk/status/2112591749562724532", "text": "True", "name": "Elon Musk", "handle": "elonmusk", "avatar": "https://pbs.twimg.com/profile_images/2103567689515954176/aR-Kjpp4_200x200.jpg", "likes": 55493, "rts": 5990, "replies": 1485, "views": 27497391, "ts": 1792516097, "media": [], "quote": {"id": "2112267729449459865", "url": "https://x.com/realBrandonGill/status/2112267729449459865", "text": "Before you go to vote, remember what is at stake.\n\nJames Talarico will be a 100% reliable vote for Chuck Schumer. He will re-open our borders, take away your Second Amendment rights, and end Texas' oil industry.\n\nHe will fight for taxpayer funded abortion through birth and trans surgeries for minors-- and rub your most deeply held Christian beliefs in your face while doing it.\n\nWe need everyone to get out and vote for @KenPaxtonTX, a leader who will deliver for us in the Senate just as he's done as our Attorney General.", "name": "Brandon Gill", "handle": "realBrandonGill", "avatar": "https://pbs.twimg.com/profile_images/2017690903096262656/l45MPM6a_200x200.jpg", "likes": 38882, "rts": 7476, "replies": 1418, "views": 27933620, "ts": 1792438845, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "Politics & World", "score": 6.12, "thread": [], "tier": "must"}]);